@ResourceLock(Resources.SYSTEM_PROPERTIES)
class NativeRuntimeValueSpillTest {
	@Test
	void spilledTriplesRetainRegisteredQueryScopedRepresentatives() {
		String previous = setBudget();
		var factory = SimpleValueFactory.getInstance();
		try (NativeExecutionContext context = new NativeExecutionContext()) {
			var representative = factory.createLiteral("a query scoped value");
			context.retainQueryScopedValue(representative, UNKNOWN);
			long representativeId = context.internGeneratedKey(representative);
			TripleTerm triple = factory.createTripleTerm(factory.createIRI("urn:subject"),
					factory.createIRI("urn:predicate"), representative);
			long tripleId = context.internGeneratedKey(triple);
			long upper = context.internGeneratedKey(factory.createLiteral("spelling", "EN"));
			long lower = context.internGeneratedKey(factory.createLiteral("spelling", "en"));
			long filesBefore = NativeRuntimeValueSpill.CREATED.get();
			for (int index = 0; index < 300; index++) {
				context.internGeneratedKey(factory.createLiteral(index + "-payload-" + "x".repeat(1024)));
			}
			assertTrue(NativeRuntimeValueSpill.CREATED.get() > filesBefore);
			assertEquals(context.runtimeValueTable().key(upper), context.runtimeValueTable().key(lower));
			assertEquals("EN", ((Literal) context.valueOf(upper)).getLanguage().orElseThrow());
			assertEquals("en", ((Literal) context.valueOf(lower)).getLanguage().orElseThrow());
			assertSame(representative, context.valueOf(representativeId));
			assertSame(representative, ((TripleTerm) context.valueOf(tripleId)).getObject(),
					"spilling must restore authoritative query-scoped representatives inside nested RDF terms");
		} finally {
			restoreBudget(previous);
		}
	}

	@Test
	void migrationPublishesAfterAnActiveStripeWriterAndItsWaitingDuplicate() throws Exception {
		String previous = setBudget();
		long created = NativeRuntimeValueSpill.CREATED.get();
		long deleted = NativeRuntimeValueSpill.DELETED.get();
		CountDownLatch insideStripe = new CountDownLatch(1);
		CountDownLatch releaseStripe = new CountDownLatch(1);
		AtomicReference<Thread> owner = new AtomicReference<>();
		AtomicReference<Thread> waiter = new AtomicReference<>();
		AtomicReference<Thread> migrator = new AtomicReference<>();
		AtomicInteger reads = new AtomicInteger();
		String heldLabel = "held runtime spelling";
		SimpleLiteral held = new SimpleLiteral(heldLabel) {
			@Override
			public String getLabel() {
				if (Thread.currentThread() == owner.get() && reads.incrementAndGet() == 2) {
					insideStripe.countDown();
					await(releaseStripe);
				}
				return super.getLabel();
			}
		};
		StringBuilder large = new StringBuilder("x".repeat(50000));
		while (stripe(large.toString()) == stripe(heldLabel)) {
			large.append('x');
		}
		var huge = SimpleValueFactory.getInstance().createLiteral(large.toString());
		try (NativeExecutionContext context = new NativeExecutionContext();
				var workers = Executors.newFixedThreadPool(3)) {
			var first = workers.submit(() -> {
				owner.set(Thread.currentThread());
				return context.internGeneratedKey(held);
			});
			assertTrue(insideStripe.await(10L, TimeUnit.SECONDS));
			var duplicate = workers.submit(() -> {
				waiter.set(Thread.currentThread());
				return context.internGeneratedKey(SimpleValueFactory.getInstance().createLiteral(heldLabel));
			});
			awaitBlocked(waiter);
			var spill = workers.submit(() -> {
				migrator.set(Thread.currentThread());
				return context.internGeneratedKey(huge);
			});
			awaitBlocked(migrator);
			releaseStripe.countDown();
			long id = first.get(10L, TimeUnit.SECONDS);
			assertEquals(id, duplicate.get(10L, TimeUnit.SECONDS));
			assertEquals(held, context.valueOf(id));
			assertEquals(huge, context.valueOf(spill.get(10L, TimeUnit.SECONDS)));
			assertEquals(id, context.internGeneratedKey(held));
			assertTrue(NativeRuntimeValueSpill.CREATED.get() > created);
		} finally {
			releaseStripe.countDown();
			restoreBudget(previous);
		}
		assertEquals(NativeRuntimeValueSpill.CREATED.get() - created, NativeRuntimeValueSpill.DELETED.get() - deleted);
	}

	@Test
	void cancellationDuringMigrationClosesAllUnpublishedSpillFiles() {
		String previous = setBudget();
		long created = NativeRuntimeValueSpill.CREATED.get();
		long deleted = NativeRuntimeValueSpill.DELETED.get();
		AtomicBoolean armed = new AtomicBoolean();
		NativeExecutionContext context = new NativeExecutionContext();
		SimpleLiteral first = new SimpleLiteral("cancel migration") {
			@Override
			public String getLabel() {
				if (armed.getAndSet(false)) {
					context.cancellation().requestCancellation();
				}
				return super.getLabel();
			}
		};
		try (context) {
			context.internGeneratedKey(first);
			armed.set(true);
			assertThrows(KernelQueryCancelledException.class,
					() -> context
							.internGeneratedKey(SimpleValueFactory.getInstance().createLiteral("x".repeat(50000))));
			assertTrue(NativeRuntimeValueSpill.CREATED.get() > created);
		} finally {
			restoreBudget(previous);
		}
		assertEquals(0L, context.queryRuntimeValueAccountedBytes());
		assertEquals(NativeRuntimeValueSpill.CREATED.get() - created, NativeRuntimeValueSpill.DELETED.get() - deleted);
	}

	private static void await(CountDownLatch latch) {
		try {
			assertTrue(latch.await(10L, TimeUnit.SECONDS));
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError(failure);
		}
	}

	private static void awaitBlocked(AtomicReference<Thread> reference) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10L);
		while (System.nanoTime() < deadline) {
			Thread thread = reference.get();
			if (thread != null && thread.getState() == Thread.State.BLOCKED) {
				return;
			}
			Thread.yield();
		}
		throw new AssertionError("runtime dictionary writer did not reach its controlled monitor boundary");
	}

	/** Selects independent arena stripes only; correctness assertions do not depend on the hash result. */
	private static int stripe(String label) {
		int hash = label.hashCode();
		hash ^= hash >>> 16;
		hash *= 0x7feb352d;
		hash ^= hash >>> 15;
		hash *= 0x846ca68b;
		hash ^= hash >>> 16;
		return hash >>> 28;
	}

	private static String setBudget() {
		String previous = System.getProperty(NativeRuntimeValueTable.MAX_BYTES_PROPERTY);
		System.setProperty(NativeRuntimeValueTable.MAX_BYTES_PROPERTY, "65536");
		return previous;
	}

	private static void restoreBudget(String previous) {
		if (previous == null) {
			System.clearProperty(NativeRuntimeValueTable.MAX_BYTES_PROPERTY);
		} else {
			System.setProperty(NativeRuntimeValueTable.MAX_BYTES_PROPERTY, previous);
		}
	}
}
